import { useId, useState } from 'react';
import { DialogHeader } from '@kerfjs/ui/dialog-header';
import { EmptyState } from '@kerfjs/ui/empty-state';
import './command-palette.css';

type Command = { id: string; group: string; label: string };
type Props = { open: boolean; commands: Command[]; recentIds: string[]; onRun: (id: string) => void; onClose: () => void };

export function CommandPalette({ open, commands, recentIds, onRun, onClose }: Props) {
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const titleId = useId();
  const filtered = commands.filter(command => command.label.toLowerCase().includes(query.toLowerCase()));
  const recent = recentIds.map(id => filtered.find(command => command.id === id)).filter((item): item is Command => Boolean(item));
  const groups = new Map<string, Command[]>();
  for (const command of filtered) groups.set(command.group, [...(groups.get(command.group) ?? []), command]);

  function onKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'ArrowDown') { event.preventDefault(); setActive(index => Math.min(index + 1, filtered.length - 1)); }
    if (event.key === 'ArrowUp') { event.preventDefault(); setActive(index => Math.max(index - 1, 0)); }
    if (event.key === 'Enter' && filtered[active]) onRun(filtered[active].id);
    if (event.key === 'Escape') onClose();
  }

  return (
    <dialog open={open} className="command-palette" aria-labelledby={titleId}>
      <DialogHeader id={titleId} title="Command palette" />
      <input autoFocus type="search" role="combobox" aria-label="Find a command" aria-controls="command-results" aria-expanded="true" aria-activedescendant={filtered[active] ? `command-${filtered[active].id}` : undefined} value={query} onChange={event => { setQuery(event.target.value); setActive(0); }} onKeyDown={onKeyDown} />
      <div className="palette-results">
        {filtered.length === 0 ? <EmptyState title="No matching commands" description="Try a different search." /> : (
          <div id="command-results" role="listbox" aria-label="Commands">
            {query === '' && recent.length > 0 && <CommandGroup label="Recent" commands={recent} active={filtered[active]?.id} onRun={onRun} />}
            {[...groups].map(([label, group]) => <CommandGroup key={label} label={label} commands={group} active={filtered[active]?.id} onRun={onRun} />)}
          </div>
        )}
      </div>
    </dialog>
  );
}

function CommandGroup({ label, commands, active, onRun }: { label: string; commands: Command[]; active?: string; onRun: (id: string) => void }) {
  return <section aria-label={label}><h2>{label}</h2>{commands.map(command => <button id={`command-${command.id}`} key={command.id} role="option" aria-selected={command.id === active} type="button" onClick={() => onRun(command.id)}>{command.label}</button>)}</section>;
}

