.command-palette { inline-size: min(40rem, calc(100vw - 2rem)); max-block-size: min(42rem, calc(100dvh - 2rem)); padding: 0; }
.command-palette > input { box-sizing: border-box; inline-size: calc(100% - 2 * var(--kui-space-dialog)); min-block-size: 2.75rem; margin: var(--kui-space-dialog); }
.palette-results { max-block-size: 28rem; overflow: auto; padding: 0 var(--kui-space-dialog) var(--kui-space-dialog); }
.palette-results section { display: grid; gap: var(--kui-space-control); }
.palette-results h2 { font: inherit; font-weight: 600; }
.palette-results [role='option'] { min-block-size: 2.75rem; text-align: start; }
